<?php
$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$url=trim($_POST['source_url']??'');$type=$_POST['resource_type']??'link';$path=null;
 if(isset($_FILES['resource_file'])&&$_FILES['resource_file']['error']===UPLOAD_ERR_OK){$f=$_FILES['resource_file'];if($f['size']>UPLOAD_MAX_BYTES){flash('File exceeds upload limit.','error');redirect('index.php?page=resources');}$allowed=['pdf'=>'application/pdf','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document','pptx'=>'application/vnd.openxmlformats-officedocument.presentationml.presentation','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','txt'=>'text/plain','csv'=>'text/csv','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$ext])){flash('File type not allowed.','error');redirect('index.php?page=resources');}$name=bin2hex(random_bytes(16)).'.'.$ext;$dest=__DIR__.'/../storage/uploads/'.$name;if(!move_uploaded_file($f['tmp_name'],$dest)){flash('Upload failed.','error');redirect('index.php?page=resources');}$path=$name;$type='file';}
 if($title!==''){$pdo->prepare('INSERT INTO resources(title,resource_type,source_url,file_path,description) VALUES(?,?,?,?,?)')->execute([$title,$type,$url?:null,$path,trim($_POST['description']??'')]);flash('Resource saved.');}redirect('index.php?page=resources');}
$rows=$pdo->query('SELECT * FROM resources ORDER BY created_at DESC')->fetchAll();
?><div class="page-heading"><div><p class="eyebrow">KNOWLEDGE REPOSITORY</p><h1>Resource Library</h1><p class="muted">Collect books, papers, videos and useful learning links.</p></div></div>
<div class="two-col"><section class="card"><h2>Add a resource</h2><form method="post" enctype="multipart/form-data" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Title</label><input name="title" required><label>Source URL (optional)</label><input type="url" name="source_url" placeholder="https://"><label>Upload file (optional)</label><input type="file" name="resource_file"><small class="muted">Allowed: PDF, Office documents, CSV, TXT and images. Maximum 15 MB.</small><label>Description / tags</label><textarea name="description" rows="3"></textarea><button class="btn primary">Save resource</button></form></section><section class="card"><div class="card-head"><h2>Saved resources</h2><span class="pill neutral"><?=count($rows)?> items</span></div><?php if(!$rows):?><div class="empty-state compact">Your library is ready for its first resource.</div><?php else:foreach($rows as $r):?><div class="list-item"><div class="list-icon">▤</div><div class="grow"><b><?=e($r['title'])?></b><small><?=e($r['resource_type'])?> · <?=e($r['description']??'')?></small><?php if($r['source_url']):?><a href="<?=e($r['source_url'])?>" target="_blank" rel="noopener">Open source ↗</a><?php elseif($r['file_path']):?><small>Stored privately: <?=e($r['file_path'])?></small><?php endif;?></div></div><?php endforeach;endif;?></section></div>
